CREATE TRIGGER `compliance_case_assignments_links_guard` BEFORE INSERT ON `compliance_case_assignments` WHEN ( NOT EXISTS ( SELECT 1 FROM `compliance_cases` compliance_case WHERE compliance_case.`id` = NEW.`case_id` AND compliance_case.`organisation_id` = NEW.`organisation_id` ) OR NOT EXISTS ( SELECT 1 FROM `compliance_users` compliance_user WHERE compliance_user.`id` = NEW.`compliance_user_id` AND compliance_user.`organisation_id` = NEW.`organisation_id` AND ( (NEW.`assignment_role` = 'case_manager' AND compliance_user.`role` IN ('admin', 'case_manager')) OR (NEW.`assignment_role` IN ('primary_reviewer', 'secondary_reviewer') AND compliance_user.`role` IN ('admin', 'reviewer')) OR (NEW.`assignment_role` = 'auditor' AND compliance_user.`role` IN ('admin', 'auditor')) ) ) ) BEGIN SELECT RAISE(ABORT, 'COMPLIANCE_ASSIGNMENT_LINK_INVALID'); END;
CREATE TRIGGER `compliance_case_tasks_links_insert_guard` BEFORE INSERT ON `compliance_case_tasks` WHEN ( NOT EXISTS ( SELECT 1 FROM `compliance_cases` compliance_case WHERE compliance_case.`id` = NEW.`case_id` AND compliance_case.`organisation_id` = NEW.`organisation_id` ) OR ( NEW.`assignee_user_id` <> '' AND NOT EXISTS ( SELECT 1 FROM `compliance_users` compliance_user WHERE compliance_user.`id` = NEW.`assignee_user_id` AND compliance_user.`organisation_id` = NEW.`organisation_id` ) ) ) BEGIN SELECT RAISE(ABORT, 'COMPLIANCE_TASK_LINK_INVALID'); END;
