CREATE TRIGGER `compliance_case_evidence_links_guard` BEFORE INSERT ON `compliance_case_evidence` WHEN ( NOT EXISTS ( SELECT 1 FROM `compliance_cases` compliance_case JOIN `compliance_evidence_requirements` requirement ON requirement.`id` = NEW.`requirement_id` AND requirement.`organisation_id` = compliance_case.`organisation_id` AND requirement.`policy_version_id` = compliance_case.`evidence_policy_version_id` WHERE compliance_case.`id` = NEW.`case_id` AND compliance_case.`organisation_id` = NEW.`organisation_id` ) OR ( NEW.`job_media_id` <> '' AND NOT EXISTS ( SELECT 1 FROM `trade_crm_job_media` media JOIN `compliance_cases` compliance_case ON compliance_case.`id` = NEW.`case_id` WHERE media.`id` = NEW.`job_media_id` AND media.`work_order_id` = compliance_case.`work_order_id` AND media.`firebase_uid` = compliance_case.`installer_uid` AND compliance_case.`organisation_id` = NEW.`organisation_id` ) ) OR ( NEW.`supersedes_evidence_id` <> '' AND NOT EXISTS ( SELECT 1 FROM `compliance_case_evidence` superseded WHERE superseded.`id` = NEW.`supersedes_evidence_id` AND superseded.`organisation_id` = NEW.`organisation_id` AND superseded.`case_id` = NEW.`case_id` AND superseded.`requirement_id` = NEW.`requirement_id` ) ) ) BEGIN SELECT RAISE(ABORT, 'COMPLIANCE_EVIDENCE_LINK_INVALID'); END;
CREATE TRIGGER `compliance_case_findings_links_guard` BEFORE INSERT ON `compliance_case_findings` WHEN ( NOT EXISTS ( SELECT 1 FROM `compliance_cases` compliance_case WHERE compliance_case.`id` = NEW.`case_id` AND compliance_case.`organisation_id` = NEW.`organisation_id` ) OR ( NEW.`evidence_id` <> '' AND NOT EXISTS ( SELECT 1 FROM `compliance_case_evidence` evidence WHERE evidence.`id` = NEW.`evidence_id` AND evidence.`organisation_id` = NEW.`organisation_id` AND evidence.`case_id` = NEW.`case_id` AND ( NEW.`requirement_id` = '' OR evidence.`requirement_id` = NEW.`requirement_id` ) ) ) OR ( NEW.`requirement_id` <> '' AND NOT EXISTS ( SELECT 1 FROM `compliance_cases` compliance_case JOIN `compliance_evidence_requirements` requirement ON requirement.`id` = NEW.`requirement_id` AND requirement.`organisation_id` = compliance_case.`organisation_id` AND requirement.`policy_version_id` = compliance_case.`evidence_policy_version_id` WHERE compliance_case.`id` = NEW.`case_id` AND compliance_case.`organisation_id` = NEW.`organisation_id` ) ) ) BEGIN SELECT RAISE(ABORT, 'COMPLIANCE_FINDING_LINK_INVALID'); END;
