CREATE TRIGGER `compliance_decision_requests_secondary_update_guard` BEFORE UPDATE OF `status`, `secondary_reviewer_uid` ON `compliance_decision_requests` WHEN ( NEW.`status` = 'approved' AND NOT EXISTS ( SELECT 1 FROM `compliance_users` primary_reviewer WHERE primary_reviewer.`firebase_uid` = NEW.`primary_reviewer_uid` AND primary_reviewer.`organisation_id` = NEW.`organisation_id` AND primary_reviewer.`status` = 'active' AND primary_reviewer.`role` IN ('admin', 'reviewer') ) ) OR ( NEW.`status` = 'approved' AND NOT EXISTS ( SELECT 1 FROM `compliance_cases` compliance_case WHERE compliance_case.`id` = NEW.`case_id` AND compliance_case.`organisation_id` = NEW.`organisation_id` AND compliance_case.`revision` = NEW.`case_revision` ) ) OR ( NEW.`secondary_reviewer_uid` <> '' AND NOT EXISTS ( SELECT 1 FROM `compliance_users` secondary_reviewer WHERE secondary_reviewer.`firebase_uid` = NEW.`secondary_reviewer_uid` AND secondary_reviewer.`organisation_id` = NEW.`organisation_id` AND secondary_reviewer.`status` = 'active' AND secondary_reviewer.`role` IN ('admin', 'reviewer') ) ) BEGIN SELECT RAISE(ABORT, 'COMPLIANCE_DECISION_REQUEST_REVIEWER_INVALID'); END;
